@@ -0,0 +1,62 @@
+interface NotificationChannel {
+  type: "email" | "sms" | "push" | "slack";
+  enabled: boolean;
+  frequency: "immediate" | "hourly" | "daily";
+}
+
+interface UserPreferences {
+  userId: string;
+  channels: NotificationChannel[];
+  quietHoursStart: number | undefined;
+  quietHoursEnd: number | undefined;
+  timezone: string;
+}
+
+var DEFAULT_CHANNELS: NotificationChannel[] = [
+  { type: "email", enabled: true, frequency: "immediate" },
+  { type: "push", enabled: true, frequency: "immediate" },
+  { type: "sms", enabled: false, frequency: "daily" },
+  { type: "slack", enabled: false, frequency: "hourly" },
+];
+
+export function mergePreferences(
+  saved: Partial<UserPreferences> | undefined,
+  overrides: Partial<UserPreferences> | undefined
+): UserPreferences {
+  var userId = saved?.userId ?? overrides?.userId ?? "unknown";
+  var timezone = overrides?.timezone ?? saved?.timezone ?? "UTC";
+
+  var channelMap = new Map<string, NotificationChannel>();
+
+  DEFAULT_CHANNELS.forEach(function (ch) {
+    channelMap.set(ch.type, { ...ch });
+  });
+
+  if (saved !== undefined && saved.channels !== undefined) {
+    saved.channels.forEach(function (ch) {
+      channelMap.set(ch.type, { ...ch });
+    });
+  }
+
+  if (overrides !== undefined && overrides.channels !== undefined) {
+    overrides.channels.forEach(function (ch) {
+      var existing = channelMap.get(ch.type);
+      channelMap.set(ch.type, existing ? { ...existing, ...ch } : { ...ch });
+    });
+  }
+
+  var quietStart = overrides?.quietHoursStart !== undefined
+    ? overrides.quietHoursStart
+    : saved?.quietHoursStart;
+  var quietEnd = overrides?.quietHoursEnd !== undefined
+    ? overrides.quietHoursEnd
+    : saved?.quietHoursEnd;
+
+  return {
+    userId: userId,
+    channels: Array.from(channelMap.values()),
+    quietHoursStart: quietStart,
+    quietHoursEnd: quietEnd,
+    timezone: timezone,
+  };
+}
